import * as z from "zod/v4";
import { SLACK_STATUS_MAX_LEN } from "../../../channels/slack/constants.js";
import { defineTool } from "../../../tools.js";
const setStatus = defineTool({
    description: [
        "Set the status line under this thread (assistant.threads.setStatus).",
        "That is the subtitle chip, not a message.",
        `Keep it under ${String(SLACK_STATUS_MAX_LEN)} characters.`,
        "Pass an empty string to clear it.",
        "The channel paints thinking on this chip from the turn. Do not use this for thinking.",
        "The tool records nothing. The channel watching this turn writes the chip.",
    ].join(" "),
    inputSchema: z.object({
        status: z.string().max(SLACK_STATUS_MAX_LEN),
    }),
    execute: ({ status }) => ({ status }),
});
export default setStatus;
